"""Append later persistence/trace findings without dropping earlier claims."""
import hashlib,json,pathlib
H=pathlib.Path(__file__).resolve().parent;P='additional_pfp_infrastructure_remaining';f=json.loads((H/(P+'_preparation.json')).read_text())['files'];rp=H/(P+'.json');r=json.loads(rp.read_text())
def ev(i,a,b):return {'path':f[i]['path'],'sha256':f[i]['sha256'],'lines':[a,b]}
rows=[
('012','Legacy raw-response recovery can escape its declared directory','Attempt IDs are only nonempty strings. _artifact_matches constructs the supposedly exact filename from that unvalidated ID, so ../outside with raw_response_path ../outside.json reads and accepts a sibling file. The repaired name equality does not establish containment.',[ev(270,594,607),ev(270,745,793),ev(271,272,291)],['PFPINFRA-P021'],'Require canonical digest IDs and reject path separators; resolve under the declared root with the intended symlink policy. V1 recovery only.'),
('013','Trace recovery can crash on malformed bytes and accepts reversed dispatch chronology','Invalid UTF8 raises UnicodeDecodeError outside the scanner refusal path. Separately, response-before-intent records can recover DISPATCH_COMPLETE because recovery joins by ID without an ordering check. These are concrete recovery gaps; the hash chain itself correctly enforces canonical bytes and links.',[ev(268,673,676),ev(270,572,729)],['PFPINFRA-P020','PFPINFRA-P022'],'Treat decoding failures as incomplete evidence and enforce intent-before-response chronology before recovery.'),
('014','Attempt identity omits some declared request controls','Attempt ID hashes system/user/provider/model/execution/index, but no output limit or other request settings. Synthetic requests with limits1 and999 have the same attempt identity. This is narrower than the docstring claim of identity over declared inputs.',[ev(270,313,347),ev(270,379,397)],['PFPINFRA-P023'],'Bind canonical full admitted wire request and relevant budget/price contract, or state exactly which projection the identity names.'),
('015','Content-address conflict raises an undefined exception name','Existing content-addressed path with nonmatching bytes attempts to raise CanonicalizationError, which is not imported or defined in json_wire. The intended integrity refusal becomes NameError; conflicting bytes are not overwritten.',[ev(251,8,34),ev(251,112,134)],['PFPINFRA-P024'],'Import the intended exception and cover the conflict branch without weakening exclusive creation.'),
('016','Some persistence and event guarantees exceed the concrete mechanism','SymbolGameDbContext writes directly despite transactional wording. Event bus/outbox use unsynchronized mutable memory and mark dispatched only after every handler returns; a partial-handler failure leaves effects to repeat on retry. FileRunRecorder has stronger staging/fsync but default git_dirty=False is unmeasured and same-process same-second same-slug run opens reuse identity.',[ev(205,12,32),ev(157,30,88),ev(206,169,218)],[],'Use accurate ephemeral/at-least-once language, explicit transaction owner and idempotent handlers; measure provenance and use unique run identities.'),
('017','Terminal routing cache returns mutable shared policy','The cached loader returns its dict object. A caller can mutate the returned mapping and alter later routing without changing the source JSON; no exact source-key coverage check is performed.',[ev(266,30,47)],[],'Cache an immutable representation and return copies or readonly views; validate exact terminal coverage.'),
('018','WDP receipt digest does not bind the mathematical arena','The adapter computes an arena/certificate but issues a receipt whose inputs contain task_id, budget and compression flag only; outputs contain label, initial value and quotient count. Original graph, initial/targets and certificate are absent, so the receipt digest cannot identify that particular mathematical instance.',[ev(275,37,103)],[],'Include canonical arena/problem and certificate digests in receipt inputs; preserve external checker premises and explicit impossibility admission.'),
]
existing={x['id']:x for x in r['findings']}
for id,title,detail,refs,probes,action in rows:existing['PFPINFRA-F'+id]={'id':'PFPINFRA-F'+id,'severity':'medium','title':title,'finding':detail,'evidence':refs,'probes':probes,'next_action':action,'status':'open','scope':'Source-local boundary and bounded synthetic controls; no private evidence or live dispatch inspected.'}
r['findings']=list(existing.values());claims={x['id']:x for x in r['claims']};claims['PFPINFRA-C006']={'id':'PFPINFRA-C006','claim':'Trace and dispatch custody distinguish byte evidence from mathematical validity: exact canonical chain, explicit seal/EOF, external expected terminal digest, nonretryable unknown dispatch, response replay and process-crash evidence ceiling are concrete mechanisms.','evidence':[ev(268,13,47),ev(268,429,483),ev(268,525,773),ev(270,379,499),ev(270,527,555)],'dependencies':['Trusted expected digest custody','External encrypted CAS semantics','Gateway pricing/admission','OS filesystem behavior'],'limitations':['No power-loss or tamper-proof claim, no provider calls, no native replay, and identified recovery gaps remain.']};claims['PFPINFRA-C007']={'id':'PFPINFRA-C007','claim':'The shared integer-sum contract has an explicit finite exact carrier and direct checker:1..1024 exact integers of magnitude at most10**100, exact total field and arithmetic recomputation.','evidence':[ev(280,43,94)],'dependencies':['Prior task schema admission','Domain strict JSON ingress'],'limitations':['This finite task does not certify generic workflow reasoning or detector adequacy. No new provider experiment.']};r['claims']=list(claims.values())
v={x['path']:x for x in r['validation']};vp=P+'_checks03.json';v[vp]={'path':vp,'sha256':hashlib.sha256((H/vp).read_bytes()).hexdigest(),'controls':5,'result':'all reproduced','scope':'Fully read AST fragments; synthetic records and files under task-owned temporary subtree; no production imports/provider/native/private access.'};r['validation']=list(v.values());rp.write_text(json.dumps(r,indent=2)+'\n')
(H/(P+'.md')).write_text(f"# PFP infrastructure audit — in progress\n\n{r['full_source_read_count']}/{r['scope_count']} frozen files have complete substantive body reviews; {len(r['remaining_work'])} remain. Parsing and emission do not grant review credit.\n\nThe report currently has {len(r['claims'])} claims, {len(r['findings'])} actionable findings and24 reproduced offline controls. Normal-form replay/minimization labels, route-based admission and demo authority dictionaries have concrete counterexamples. Persistence and recovery checks expose median omission, partial commits, composite-key collisions, legacy response path traversal and incomplete dispatch identities.\n\nUseful mechanisms include explicit declared-FD limits in the SQL pipeline, witness-body checks in the concrete seed verifier, exact finite integer-sum admission, canonical trace-byte checks and response replay before dispatch completion. These do not establish generic mathematical certification, power-loss durability or provider effectiveness.\n\nDetailed source hashes/ranges, exact counterexamples and per-file limitations are in the JSON report. No source changes, providers, native builds or private benchmark material were used.\n")
print(json.dumps({'claims':len(r['claims']),'findings':len(r['findings']),'full':r['full_source_read_count']}))
